SELECT CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END launch_cohort, DATE_FORMAT(p.launch_date, 'yyyy-MM') launch_month, COUNT(DISTINCT i.quantity) unique_products, MAX(i.quantity) max_quantity FROM inventory i JOIN products p ON p.id = i.product_id GROUP BY CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END, DATE_FORMAT(p.launch_date, 'yyyy-MM') HAVING unique_products > 1 ORDER BY launch_cohort ASC;
